const TITLES = {
  provider: 'Provider',
  overview: 'Overview',
  inbox: 'Inbox',
  compare: 'Compare',
  directory: 'Directory',
  providers: 'Providers',
  shortlists: 'Shortlists',
  requests: 'Requests',
  intelligence: 'Intelligence',
  profile: 'Profile',
  settings: 'Settings',
}
const DEFAULT_FAVS = [
  {
    id: 'f1',
    label: 'EUR → USD payouts',
    kind: 'corridor',
    page: 'compare',
    params: { ids: ['ledgerline', 'swiftrail', 'iberia'], savedId: 'c1' },
  },
  { id: 'f2', label: 'KYC shortlist', kind: 'shortlist', page: 'shortlists', params: { initial: 's1' } },
  { id: 'f3', label: 'FX benchmarks', kind: 'benchmark', page: 'intelligence', params: { tab: 'benchmarks' } },
  { id: 'f4', label: 'Licence watch', kind: 'watch', page: 'intelligence', params: { tab: 'licences' } },
]
const LISTS = [
  {
    id: 's1',
    name: 'KYC shortlist',
    kind: 'kyc',
    updated: 'today',
    note: 'Need EU and UK coverage with video ident by Q1.',
    ids: ['kestrel', 'veritas', 'orbis', 'proofline'],
  },
  {
    id: 's2',
    name: 'EU payout partners',
    kind: 'payouts',
    updated: 'Mon',
    note: '',
    ids: ['ledgerline', 'swiftrail', 'iberia'],
  },
  {
    id: 's3',
    name: 'Sponsor banks',
    kind: 'bank',
    updated: 'Oct 10',
    note: 'Safeguarding plus virtual IBANs.',
    ids: ['albion', 'nordhavn', 'helix'],
  },
  {
    id: 's4',
    name: 'FX for APAC launch',
    kind: 'fx',
    updated: 'Oct 9',
    note: 'AUD, JPY and SGD priority.',
    ids: ['pacifica', 'meridian', 'cobalt'],
  },
]
const COMPARES = [
  { id: 'c1', name: 'EUR → USD payouts', kind: 'payouts', ids: ['ledgerline', 'swiftrail', 'iberia'] },
  { id: 'c2', name: 'Sponsor banks in Europe', kind: 'bank', ids: ['albion', 'nordhavn', 'lucerna'] },
]
const KIND = { compare: 'corridor', shortlists: 'shortlist', intelligence: 'benchmark' }
const same = (a, b) => JSON.stringify(a ?? {}) === JSON.stringify(b ?? {})
class Component extends DCLogic {
  state = {
    page: this.props.initialRoute?.page ?? 'overview',
    params: this.props.initialRoute?.params ?? {},
    activeKey: this.props.initialRoute?.page ?? 'overview',
    favs: DEFAULT_FAVS,
    lists: LISTS,
    compares: COMPARES,
    modal: null,
    toasts: [],
    tn: 0,
    confirm: null,
    plan: this.props.plan ?? (/[?&]plan=pro/i.test(dcSearch()) ? 'Pro' : 'Free'),
    focusList: null,
    n: 10,
    navOpen: false,
  }
  flash(title, type = 'success', desc, extra) {
    const id = 't' + Date.now() + Math.random()
    this.setState((s) => ({ toasts: [...s.toasts, { id, type, title, desc, ...extra }].slice(-3) }))
    if (type !== 'error') setTimeout(() => this.drop(id), 4200)
  }
  drop(id) {
    this.setState((s) => ({ toasts: s.toasts.map((t) => (t.id === id ? { ...t, leaving: true } : t)) }))
    setTimeout(() => this.setState((s) => ({ toasts: s.toasts.filter((t) => t.id !== id) })), 260)
  }
  ask(c) {
    this.setState({ confirm: c })
  }
  go(page, params = {}, key) {
    this.setState({ page, params, activeKey: key ?? page, navOpen: false })
    this.props.onRoute?.(page, params)
  }
  componentDidUpdate(prev) {
    const r = this.props.route
    if (r && r !== prev.route && (r.page !== this.state.page || !same(r.params, this.state.params)))
      this.setState({ page: r.page, params: r.params, activeKey: r.page, navOpen: false })
    if (this.props.plan && this.props.plan !== prev.plan) this.setState({ plan: this.props.plan })
  }
  renderVals() {
    const S = this.state
    const fav = S.favs.find((f) => f.page === S.page && same(f.params, S.params))
    const cmpName = S.page === 'compare' && S.params.savedId && S.compares.find((c) => c.id === S.params.savedId)?.name
    const prov = S.page === 'provider' ? RELAY?.byId[S.params.id] : null
    const title = fav?.label || cmpName || prov?.name || TITLES[S.page] || 'Overview'
    const upd = (id, fn) =>
      this.setState((s) => ({ lists: s.lists.map((l) => (l.id === id ? { ...fn(l), updated: 'today' } : l)) }))
    return {
      is: { [S.page]: true },
      page: S.page,
      params: S.params,
      title,
      activeKey: fav?.id ?? (S.page === 'provider' ? (S.params.from ?? 'directory') : S.activeKey),
      starred: !!fav,
      favs: S.favs,
      lists: S.lists,
      compares: S.compares,
      modal: S.modal,
      plan: S.plan,
      focusList: S.focusList,
      onNavigate: (k, params) => {
        const f = S.favs.find((x) => x.id === k)
        if (f) return this.go(f.page, f.params, f.id)
        this.go(k, params ?? {})
      },
      onCompare: (ids) => this.go('compare', { ids }),
      openProvider: (id, from) => this.go('provider', { id, from: from ?? S.page }, from ?? S.page),
      onToast: (title, type, desc) => this.flash(title, type, desc),
      dropToast: (id) => this.drop(id),
      cf: S.confirm
        ? { open: true, tone: 'danger', ok: 'Delete', item: '', kind: 'all', meta: '', ...S.confirm }
        : { open: false, title: '', body: '', ok: '', item: '', kind: 'all', meta: '', tone: 'danger' },
      cfYes: () => {
        const c = S.confirm
        this.setState({ confirm: null })
        c?.run?.()
      },
      cfNo: () => this.setState({ confirm: null }),
      onStar: (on) => {
        if (!on) {
          this.setState((s) => ({ favs: s.favs.filter((f) => !(f.page === s.page && same(f.params, s.params))) }))
          return this.flash('Removed from favorites', 'info')
        }
        this.setState((s) => ({
          n: s.n + 1,
          favs: [
            ...s.favs,
            { id: 'f' + s.n, label: title, kind: KIND[s.page] ?? 'page', page: s.page, params: s.params },
          ],
        }))
        this.flash('Added to favorites', 'success', title + ' is pinned in the sidebar.')
      },
      removeFav: (id) => this.setState((s) => ({ favs: s.favs.filter((f) => f.id !== id) })),
      restoreFavs: () => this.setState({ favs: DEFAULT_FAVS }),
      addToShortlist: (ids) => this.setState({ modal: { type: 'addTo', ids } }),
      openUpgrade: () => this.setState({ modal: { type: 'upgrade' } }),
      closeModal: () => this.setState({ modal: null }),
      confirmUpgrade: () => {
        this.setState({ modal: null, plan: 'Pro' })
        this.props.onUpgradePlan?.()
        this.flash('Welcome to Relay Pro', 'success', 'The full directory is now unlocked.')
      },
      addToLists: (listIds, ids) => {
        this.setState((s) => ({
          modal: null,
          lists: s.lists.map((l) =>
            listIds.includes(l.id) ? { ...l, ids: [...new Set([...l.ids, ...ids])], updated: 'today' } : l,
          ),
        }))
        this.flash(
          listIds.length === 1
            ? 'Added to ' + S.lists.find((l) => l.id === listIds[0])?.name
            : `Added to ${listIds.length} shortlists`,
        )
      },
      createList: () => this.setState({ modal: { type: 'edit' } }),
      editList: (id) => this.setState({ modal: { type: 'edit', id } }),
      saveList: (l) => {
        if (l.id) {
          upd(l.id, (x) => ({ ...x, name: l.name, kind: l.kind, note: l.note }))
          this.setState({ modal: null })
          return this.flash('Shortlist updated')
        }
        const id = 's' + S.n
        this.setState((s) => ({
          n: s.n + 1,
          modal: null,
          focusList: id,
          lists: [{ id, name: l.name, kind: l.kind, note: l.note, ids: l.ids, updated: 'today' }, ...s.lists],
        }))
        this.flash('Shortlist created')
      },
      deleteList: (id) => {
        const l = S.lists.find((x) => x.id === id)
        this.ask({
          title: 'Delete shortlist?',
          body: 'This removes the shortlist and its notes for everyone in your workspace. This can’t be undone.',
          ok: 'Delete shortlist',
          item: l?.name,
          kind: l?.kind,
          meta: (l?.ids.length ?? 0) + ' Providers · Updated ' + l?.updated,
          run: () => {
            this.setState((s) => ({
              modal: null,
              lists: s.lists.filter((x) => x.id !== id),
              favs: s.favs.filter((f) => f.params?.initial !== id),
            }))
            this.flash('Shortlist deleted', 'success', (l?.name ?? 'Shortlist') + ' was removed.')
          },
        })
      },
      noteList: (id, note) => upd(id, (l) => ({ ...l, note })),
      removeItem: (id, pid) => upd(id, (l) => ({ ...l, ids: l.ids.filter((x) => x !== pid) })),
      addItems: (id, ids) => {
        upd(id, (l) => ({ ...l, ids: [...new Set([...l.ids, ...ids])] }))
        this.flash(`${ids.length} Provider${ids.length === 1 ? '' : 's'} added`)
      },
      saveCompare: (c) => {
        this.setState((s) => ({
          compares: s.compares.some((x) => x.id === c.id)
            ? s.compares.map((x) => (x.id === c.id ? c : x))
            : [c, ...s.compares],
          params: { ids: c.ids, savedId: c.id },
        }))
        this.flash('Comparison saved')
      },
      deleteCompare: (id) => {
        const c = S.compares.find((x) => x.id === id)
        this.ask({
          title: 'Delete saved comparison?',
          body: 'It will be removed from Compare and from Favorites.',
          ok: 'Delete',
          item: c?.name,
          kind: c?.kind,
          meta: (c?.ids.length ?? 0) + ' Providers',
          run: () => {
            this.setState((s) => ({
              compares: s.compares.filter((x) => x.id !== id),
              favs: s.favs.filter((f) => f.params?.savedId !== id),
            }))
            this.flash('Comparison deleted', 'success')
          },
        })
      },
      toasts: S.toasts,
      navOpen: S.navOpen,
      navOpenStr: String(S.navOpen),
      openNav: () => this.setState({ navOpen: true }),
      closeNav: () => this.setState({ navOpen: false }),
    }
  }
}

{
  const designVals = Component.prototype.renderVals
  const appVals = function (v) {
    const rep = this.state.page === 'report' ? getReportEntry(this.state.params.slug, 'app') : null
    return {
      appOpenReport: (slug) => this.go('report', { slug }, 'intelligence'),
      ...(rep ? { title: rep.cardTitle, activeKey: 'intelligence', page: 'intelligence' } : {}),
      ...dashboardVals.call(this, v),
    }
  }
  Component.prototype.renderVals = function () {
    const v = designVals.call(this)
    return { ...v, ...appVals.call(this, v) }
  }
}

Component = wireDashboard(Component)

